function safeTar(p){const s=cp.execFileSync('tar',['-tzf',p],{encoding:'utf8',maxBuffer:64*1024*1024});for(const raw of s.split(/\r?\n/)){const n=raw.trim().replace(/^\.\//,'');if(!n)continue;assert(!path.posix.isAbsolute(n)&&!n.split('/').includes('..'),`unsafe base carrier member ${n}`)}}
function readJson(rel){const p=path.join(target,rel);assert(fs.existsSync(p),`missing ${rel}`);return JSON.parse(fs.readFileSync(p,'utf8'))}
function walkFiles(dir,prefix=''){let out=[];for(const e of fs.readdirSync(dir,{withFileTypes:true})){const r=prefix?`${prefix}/${e.name}`:e.name,p=path.join(dir,e.name);if(e.isDirectory())out=out.concat(walkFiles(p,r));else if(e.isFile())out.push(r)}return out}
function criticalTree(){const prefixes=['public/','lib/','data/','governance/current/'];const extras=new Set(['server.js','package.json','package-lock.json','.pre103-overlay.json','.pre104-overlay.json']);const rows=[];for(const rel of walkFiles(target)){if(!(extras.has(rel)||prefixes.some(x=>rel.startsWith(x))))continue;const p=path.join(target,rel),st=fs.statSync(p);rows.push([rel,st.mode&0o7777,st.size,shaFile(p)])}rows.sort((a,b)=>a[0].localeCompare(b[0]));const h=crypto.createHash('sha256');for(const [r,m,s,d] of rows)h.update(`${r}\0${m.toString(8)}\0${s}\0${d}\n`);return {sha:h.digest('hex'),files:rows.length}}
function countHtml(dir){let n=0;for(const e of fs.readdirSync(dir,{withFileTypes:true})){const p=path.join(dir,e.name);if(e.isDirectory())n+=countHtml(p);else if(e.isFile()&&e.name.endsWith('.html'))n++;}return n}
assert(baseArchive,'exact PRE103 base carrier missing');assert(fs.statSync(baseArchive).size===BASE_BYTES,'base carrier bytes mismatch');assert(shaFile(baseArchive)===BASE_SHA,'base carrier SHA mismatch');safeTar(baseArchive);
assert(patchParts.length===11,`expected 11 patch chunks, got ${patchParts.length}`);const patchGz=Buffer.from(patchParts.map(n=>fs.readFileSync(path.join(root,n),'utf8').replace(/\s+/g,'')).join(''),'base64');assert(patchGz.length===PATCH_GZ_BYTES,'patch gzip byte mismatch');assert(shaBuf(patchGz)===PATCH_GZ_SHA,'patch gzip SHA mismatch');const patch= zlib.gunzipSync(patchGz);assert(patch.length===PATCH_BYTES,'patch byte mismatch');assert(shaBuf(patch)===PATCH_SHA,'patch SHA mismatch');assert(fs.existsSync(simpleListPath)&&shaFile(simpleListPath)===SIMPLE_SHA,'simple HTML transform list mismatch');const simpleList=JSON.parse(fs.readFileSync(simpleListPath,'utf8'));
