const token='<link rel="stylesheet" href="/pre103.css">';for(const rel of simpleList){assert(/^public\/.*\.html$/.test(rel)&&!rel.split('/').includes('..'),`unsafe transform path ${rel}`);const p=path.join(target,rel);assert(fs.existsSync(p),`transform target missing ${rel}`);const s=fs.readFileSync(p,'utf8');assert(s.includes(token),`transform token missing ${rel}`);fs.writeFileSync(p,s.replace(token,''))}
const ct=criticalTree();assert(ct.files===726,`critical runtime file count mismatch ${ct.files}`);assert(ct.sha===CRITICAL_TREE_SHA,`critical runtime tree mismatch ${ct.sha}`);
