const npm=process.platform==='win32'?'npm.cmd':'npm';cp.execFileSync(npm,['--prefix',target,'ci','--omit=dev','--no-audit','--no-fund','--ignore-scripts'],{stdio:'inherit',env:{...process.env,NPM_CONFIG_AUDIT:'false',NPM_CONFIG_FUND:'false'}});
const marker={schemaVersion:'smarter-justice.pre105.render-bootstrap.v3',release:'v2.0.0-pre105',baseCarrier:path.basename(baseArchive),baseCarrierSha256:BASE_SHA,patchParts,patchGzipSha256:PATCH_GZ_SHA,patchSha256:PATCH_SHA,criticalRuntimeTreeSha256:CRITICAL_TREE_SHA,criticalRuntimeFiles:ct.files,rogerRuleRecords:684,activeRogerRequirements:680,factoryVersion:'0.36.0',factoryCounts:factory.counts,htmlSurfaces:169,brandPromise:arch.brandPromise.english,preparedAt:new Date().toISOString()};fs.writeFileSync(path.join(target,'.pre105-render-bootstrap.json'),JSON.stringify(marker,null,2)+'\n');console.log(`[PRE105 DEPLOY] verified ${marker.release}; critical=${CRITICAL_TREE_SHA}; Factory=${factory.counts.total}; rules=684/680; pages=169`);
